function fmtMon(){return '#,##0.0';}
function fmtPct(){return '0.0%';}
const sh = ss.getSheetByName('Cash Flow Valuation');

// Fill median row under comps
const medianFormulas = [[
  '=MEDIAN(D16:D21)',
  '=MEDIAN(E16:E21)',
  '=MEDIAN(F16:F21)',
  '=MEDIAN(G16:G21)',
  '=MEDIAN(H16:H21)',
  '=MEDIAN(I16:I21)',
  '=MEDIAN(J16:J21)',
  '=MEDIAN(K16:K21)',
  '=MEDIAN(L16:L21)'
]];
sh.getRange('D23:L23').setFormulas(medianFormulas);

// Clear misplaced duplicate and keep supporting total beta in L24
sh.getRange('D24').clearContent();

// Fennmark table updates
sh.getRange('E29').clearContent();
sh.getRange('G29').clearContent();
sh.getRange('I29').clearContent();
sh.getRange('F29').setFormula('=F23');
sh.getRange('H29').setFormula('=H23');
sh.getRange('J29').setFormula('=J23');
sh.getRange('K29').setFormula('=Tax_Rate');
sh.getRange('L29').setFormula('=D29*(1+(1-K29)*(F29/J29))');

// Cost of debt = risk-free + 40 bps
sh.getRange('F8').setFormula('=Risk_Free_Rate+0.4%');

// Shift formulas/values from F31/F35 to L31/L35, then clear F31/F35
sh.getRange('L31').setFormula('=F6+L29*F7');
sh.getRange('L35').setFormula('=F29*F8*(1-K29)+J29*L31');
sh.getRangeList(['F31','F35']).clearContent();

// Explanation text
sh.getRange('B33').setValue('WACC = Cost of Equity * % Equity + Cost of Debt * % Debt * (1 - Tax Rate) + Cost of Preferred Stock * % Preferred Stock');

// Number formatting updates
const formats16to21 = [];
for (let r = 16; r <= 21; r++) {
  formats16to21.push([fmtMon(), fmtPct(), fmtMon(), fmtPct(), fmtMon(), fmtPct(), fmtPct()]);
}
sh.getRange('E16:K21').setNumberFormats(formats16to21);
sh.getRange('E29:K29').setNumberFormats([[fmtMon(), fmtPct(), fmtMon(), fmtPct(), fmtMon(), fmtPct(), fmtPct()]]);

SpreadsheetApp.flush();

log({
  D23L24: sh.getRange('D23:L24').getDisplayValues(),
  row29: sh.getRange('D29:L29').getDisplayValues(),
  inputs: sh.getRange('F6:F11').getDisplayValues(),
  moved: sh.getRange('F31:L35').getDisplayValues()
});
